import re
from pydantic import BaseModel, ValidationError
import json

def validar_salida(respuesta: str, system_prompt: str) -> dict:
    problemas = []
    # Filtración del system prompt
    if any(f in respuesta for f in system_prompt.split(".")):
        problemas.append("Filtración del system prompt detectada.")
    # PII: tarjeta de crédito
    if re.search(r'\b\d{4}[- ]?\d{4}[- ]?\d{4}[- ]?\d{4}\b', respuesta):
        problemas.append("Número de tarjeta detectado.")
    # PII: correo electrónico
    if re.search(r'[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}', respuesta):
        problemas.append("Correo electrónico detectado.")
    bloqueada = "[Respuesta bloqueada por política de seguridad]"
    return {"aprobada": not problemas, "problemas": problemas,

            "respuesta": respuesta if not problemas else bloqueada}

# Validación de formato estructurado con Pydantic
class RespuestaProducto(BaseModel):
    nombre_producto: str
    precio: float
    disponible: bool
try:
    d = RespuestaProducto(**json.loads('{"nombre_producto":"Laptop X1","precio":1299.99,"disponible":true}'))
    print(f"✅ Válida: {d}")
except ValidationError as e:
    print(f"❌ Esquema inválido: {e}")

